import org.springframework.context.annotation.*;
import org.springframework.transaction.TransactionDefinition;
import org.springframework.transaction.annotation.*;
import org.springframework.transaction.support.*;

// DB の代わりに「開始・コミット・ロールバック」を表示するだけの
// トランザクションマネージャ(ここは読み飛ばしてOK)
class LogTxManager extends AbstractPlatformTransactionManager {
    protected Object doGetTransaction() {
        return TransactionSynchronizationManager.isActualTransactionActive();
    }
    protected boolean isExistingTransaction(Object tx) {
        return (Boolean) tx;
    }
    protected void doBegin(Object tx, TransactionDefinition def) {
        System.out.println("  [TX] 開始" + (def.isReadOnly() ? "(readOnly)" : ""));
    }
    protected void doCommit(DefaultTransactionStatus s) {
        System.out.println("  [TX] コミット");
    }
    protected void doRollback(DefaultTransactionStatus s) {
        System.out.println("  [TX] ロールバック");
    }
}

@Configuration @EnableTransactionManagement
class TxConfig {
    @Bean LogTxManager transactionManager() { return new LogTxManager(); }
}

class NotifyException extends Exception {   // 検査例外
    NotifyException(String m) { super(m); }
}

class OrderService {
    @Transactional(readOnly = true)
    public void find() { System.out.println("  注文を検索"); }

    @Transactional
    public void runtimeFail() {
        System.out.println("  注文を保存");
        throw new IllegalStateException("在庫不足");
    }

    // ここを変えてみよう:@Transactional(rollbackFor = NotifyException.class) にすると?
    @Transactional
    public void checkedFail() throws NotifyException {
        System.out.println("  注文を保存");
        throw new NotifyException("通知に失敗");
    }

    // ここを変えてみよう:outer にも @Transactional を付けると?
    public void outer() {
        runtimeFail();   // this.runtimeFail() なのでプロキシを通らない
    }
}

var ctx = new AnnotationConfigApplicationContext(TxConfig.class, OrderService.class);
var service = ctx.getBean(OrderService.class);
System.out.println("Bean のクラス: " + service.getClass().getSimpleName());

System.out.println("① 参照だけ(readOnly)");
service.find();
System.out.println("② RuntimeException が起きた");
try { service.runtimeFail(); } catch (RuntimeException e) { System.out.println("  例外: " + e.getMessage()); }
System.out.println("③ 検査例外が起きた");
try { service.checkedFail(); } catch (Exception e) { System.out.println("  例外: " + e.getMessage()); }
System.out.println("④ 同じクラスの中から呼んだ");
try { service.outer(); } catch (RuntimeException e) { System.out.println("  例外: " + e.getMessage()); }
ctx.close();

